import {
    CallHandler, CanActivate, Controller, ExecutionContext, Get, Injectable, MiddlewareConsumer,
    Module, NestInterceptor, NestModule, Param, PipeTransform, UseGuards, UseInterceptors,
} from "@nestjs/common"
import { tap } from "rxjs"

@Injectable() class LogPipe implements PipeTransform {
    transform(v: any) { console.log("4. Pipe"); return v }
}
@Injectable() class LogGuard implements CanActivate {
    canActivate() { console.log("2. Guard"); return true }
}
@Injectable() class LogInterceptor implements NestInterceptor {
    intercept(_: ExecutionContext, next: CallHandler) {
        console.log("3. Interceptor (oldin)")
        return next.handle().pipe(tap(() => console.log("6. Interceptor (keyin)")))
    }
}

@Controller("flow")
class FlowController {
    @Get(":id")
    @UseGuards(LogGuard)
    @UseInterceptors(LogInterceptor)
    run(@Param("id", LogPipe) id: string) {
        console.log("5. Controller")
        return { id }
    }
}

@Module({ controllers: [FlowController] })
class AppModule implements NestModule {
    configure(consumer: MiddlewareConsumer) {
        consumer.apply((_req: any, _res: any, next: () => void) => { console.log("1. Middleware"); next() }).forRoutes("*")
    }
}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/flow/1")
    await http.close()
}
main()

import { BadRequestException, Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"

@Injectable()
class EvenNumberPipe implements PipeTransform {
    transform(value: string) {
        const n = Number(value)
        if (!Number.isInteger(n) || n % 2 !== 0) {
            throw new BadRequestException(`"${value}" juft son emas`)
        }
        return n
    }
}

@Controller("even")
class EvenController {
    @Get()
    check(@Query("n", EvenNumberPipe) n: number) {
        return { n, half: n / 2 }
    }
}

@Module({ controllers: [EvenController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/even?n=10")
    await http.get("/even?n=7")
    await http.get("/even?n=abc")
    await http.close()
}
main()

