import { Body, Controller, Module, PipeTransform, Post } from "@nestjs/common"

class TrimStringsPipe implements PipeTransform {
    transform(value: unknown) {
        if (value && typeof value === "object") {
            for (const [k, v] of Object.entries(value)) if (typeof v === "string") (value as any)[k] = v.trim()
        }
        return value
    }
}

@Controller("users") class UsersController { @Post() create(@Body() b: { name: string; email: string }) { return b } }
