    await http.post("/users", { name: "  Ali  ", email: " ali@mail.uz " })
    await http.close()
}
main()

import { Controller, Get, Injectable, Module, NotFoundException, Param, PipeTransform } from "@nestjs/common"
import { getRepositoryToken, InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, Repository } from "typeorm"

@Entity() class Product { @PrimaryGeneratedColumn() id: number; @Column() name: string }

@Injectable()
class ProductByIdPipe implements PipeTransform<string, Promise<Product>> {
    constructor(@InjectRepository(Product) private readonly repo: Repository<Product>) {}
    async transform(id: string) {
        const product = await this.repo.findOneBy({ id: Number(id) })
        if (!product) throw new NotFoundException(`Mahsulot #${id} topilmadi`)
        return product
    }
}

@Controller("products")
class ProductsController {
    @Get(":id") one(@Param("id", ProductByIdPipe) product: Product) { return { found: product.name } }
}
@Module({ imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Product], synchronize: true }), TypeOrmModule.forFeature([Product])], controllers: [ProductsController], providers: [ProductByIdPipe] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.app.get<Repository<Product>>(getRepositoryToken(Product)).save({ name: "Choy" })
    await http.get("/products/1")
    await http.get("/products/9")
    await http.close()
}
main()

