import { BadRequestException, Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"

@Injectable() class Phone implements PipeTransform {
    transform(v: string) {
        const digits = String(v).replace(/\D/g, "")
        const full = digits.length === 9 ? "998" + digits : digits
        if (!/^998\d{9}$/.test(full)) throw new BadRequestException("Telefon raqami noto'g'ri")
        return "+" + full
    }
}
