import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import {
    IsString, MinLength, Validate, ValidationArguments, ValidatorConstraint, ValidatorConstraintInterface,
} from "class-validator"

@ValidatorConstraint({ name: "matchField" })
class MatchField implements ValidatorConstraintInterface {
    validate(value: any, args: ValidationArguments) {
        const [other] = args.constraints
        return value === (args.object as any)[other]
    }
    defaultMessage(args: ValidationArguments) {
        return `${args.property} va ${args.constraints[0]} mos emas`
    }
}

class ChangePasswordDto {
    @IsString() @MinLength(8) password: string
    @Validate(MatchField, ["password"]) confirm: string
}

