import { Body, Controller, Module, Post, ValidationPipe } from "@nestjs/common"
import { MinLength, registerDecorator, ValidationArguments } from "class-validator"

function Match(prop: string) {
    return (obj: object, name: string) => registerDecorator({
        name: "match", target: obj.constructor, propertyName: name, constraints: [prop],
        options: { message: `${name} ${prop} bilan bir xil bo'lishi kerak` },
        validator: { validate: (v: unknown, a: ValidationArguments) => v === (a.object as Record<string, unknown>)[a.constraints[0]] },
    })
}
class Dto { @MinLength(6) password!: string; @Match("password") confirm!: string }
@Controller("pw") class P { @Post() p(@Body() _d: Dto) { return { ok: true } } }
@Module({ controllers: [P] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe()))
    await http.post("/pw", { password: "secret1", confirm: "secret2" })
    await http.post("/pw", { password: "secret1", confirm: "secret1" })
    await http.close()
}
main()

