import { Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"
import { APP_PIPE } from "@nestjs/core"

@Injectable()
class BadWordsService {
    private words = ["yomon", "ahmoq"]
    clean(text: string) {
        return this.words.reduce((t, w) => t.replaceAll(w, "***"), text)
    }
}

@Injectable()
class CensorPipe implements PipeTransform {
    constructor(private readonly badWords: BadWordsService) {}
    transform(v: any) { return typeof v === "string" ? this.badWords.clean(v) : v }
}

