import { Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"

@Injectable()
class CamelCaseKeysPipe implements PipeTransform {
    private camel = (s: string) => s.replace(/_([a-z])/g, (_, c) => c.toUpperCase())
    private walk(v: any): any {
        if (Array.isArray(v)) return v.map(x => this.walk(x))
        if (v && typeof v === "object") {
            return Object.fromEntries(Object.entries(v).map(([k, x]) => [this.camel(k), this.walk(x)]))
        }
        return v
    }
    transform(v: any) { return this.walk(v) }
}

@Controller("import")
