@Module({ controllers: [P] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/promo", { code: "yoz2024" })
    await http.post("/promo", { code: "SOXTA" })
    await http.close()
}
main()

import { Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"

@Injectable() class SortPipe implements PipeTransform { transform(v = "") { return Object.fromEntries(v.split(",").filter(Boolean).map(f => (f.startsWith("-") ? [f.slice(1), "desc"] : [f, "asc"]))) } }
@Controller("products") class P { @Get() p(@Query("sort", SortPipe) sort: Record<string, string>) { return { sort } } }
@Module({ controllers: [P] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/products?sort=-price,name")
    await http.close()
}
main()

import { Body, Controller, Module, Patch, PipeTransform } from "@nestjs/common"

class Whitelist implements PipeTransform { constructor(private keys: string[]) {} transform(b: Record<string, unknown>) { return Object.fromEntries(Object.entries(b).filter(([k]) => this.keys.includes(k))) } }
@Controller("profile") class P { @Patch() p(@Body(new Whitelist(["name", "bio"])) b: object) { return b } }
@Module({ controllers: [P] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.patch("/profile", { name: "Ali", bio: "dev", role: "admin", balance: 999999 })
    await http.close()
}
main()

import { Body, Controller, Module, PipeTransform, Post } from "@nestjs/common"

class Defaults implements PipeTransform { constructor(private d: Record<string, unknown>) {} transform(b: Record<string, unknown>) { return { ...this.d, ...b } } }
@Controller("tasks") class T { @Post() t(@Body(new Defaults({ priority: "normal", done: false })) b: object) { return b } }
@Module({ controllers: [T] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/tasks", { title: "Kod yozish" })
    await http.post("/tasks", { title: "Deploy", priority: "high" })
    await http.close()
}
main()

import { BadRequestException, Body, Controller, Injectable, Module, PipeTransform, Post } from "@nestjs/common"

@Injectable() class OrderCheck implements PipeTransform {
    transform(b: { qty?: number; address?: string }) {
        const errors: string[] = []
        if (!b.qty || b.qty < 1) errors.push("qty kamida 1")
        if (!b.address) errors.push("address majburiy")
        if (errors.length) throw new BadRequestException(errors)
        return b
    }
}
@Controller("order") class O { @Post() o(@Body(OrderCheck) b: object) { return b } }
@Module({ controllers: [O] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/order", {})
    await http.post("/order", { qty: 2, address: "Toshkent" })
    await http.close()
}
main()

import { Controller, Get, Injectable, Module, PipeTransform, Query } from "@nestjs/common"

@Injectable() class ToWords implements PipeTransform<string | undefined, string[]> { transform(v?: string): string[] { return (v ?? "").split(/\s+/).filter(Boolean) } }
@Controller("w") class W { @Get() w(@Query("text", ToWords) words: string[]) { return { count: words.length, words } } }
@Module({ controllers: [W] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/w?text=" + encodeURIComponent("  bir  ikki uch "))
    await http.close()
}
main()

import { BadRequestException, Body, Controller, Module, PipeTransform, Post } from "@nestjs/common"

class Compose implements PipeTransform { constructor(private pipes: PipeTransform[]) {} async transform(v: unknown, m: any) { for (const p of this.pipes) v = await p.transform(v, m); return v } }
const trim: PipeTransform = { transform: (v: string) => v.trim() }
const lower: PipeTransform = { transform: (v: string) => v.toLowerCase() }
const notEmpty: PipeTransform = { transform: (v: string) => { if (!v) throw new BadRequestException("bo'sh"); return v } }
@Controller("tag") class T { @Post() t(@Body("tag", new Compose([trim, lower, notEmpty])) tag: string) { return { tag } } }
@Module({ controllers: [T] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/tag", { tag: "  NestJS " })
    await http.post("/tag", { tag: "   " })
    await http.close()
}
main()

import { BadRequestException, Controller, Get, Injectable, Module, Param, PipeTransform } from "@nestjs/common"

@Injectable() class OrderCode implements PipeTransform { transform(v: string) { if (!/^ORD-\d{4}-\d{5}$/.test(v)) throw new BadRequestException("Kod formati: ORD-YYYY-NNNNN"); return v } }
@Controller("orders") class O { @Get(":code") o(@Param("code", OrderCode) code: string) { return { code } } }
@Module({ controllers: [O] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/orders/ORD-2024-00017")
    await http.get("/orders/17")
    await http.close()
}
main()
